18	// sloDefinition is an immutable SLO document: a target objective plus the
19	// good/total counter selectors that define the measured event streams.
20	// Replacements swap the pointer atomically, so readers never observe a
21	// half-updated definition.
22	type sloDefinition struct {
23		id        string
24		objective float64
25		good      *ruleSelector
26		total     *ruleSelector
27		comment   string
28	}
29	
30	// ---- JSON wire shapes ------------------------------------------------------
31	
32	type sloJSON struct {
33		ID        string       `json:"id"`
34		Objective float64      `json:"objective"`
35		Good      ruleSideJSON `json:"good"`
36		Total     ruleSideJSON `json:"total"`
37		Comment   string       `json:"comment"`
38	}
39	
40	func sloWireJSON(d *sloDefinition) sloJSON {
41		return sloJSON{
42			ID:        d.id,
43			Objective: d.objective,
44			Good:      sideWireJSON(d.good),
45			Total:     sideWireJSON(d.total),
46			Comment:   d.comment,
47		}
48	}
