51	
52	type rawSLO struct {
53		Objective *float64     `json:"objective"`
54		Good      *rawRuleSide `json:"good"`
55		Total     *rawRuleSide `json:"total"`
56		Comment   *string      `json:"comment"`
57	}
58	
59	// decodeSLO parses and fully validates an SLO body. It never returns a
60	// partially validated definition.
61	func decodeSLO(body []byte) (*sloDefinition, bool) {
62		var raw rawSLO
63		if !strictDecode(body, &raw) {
64			return nil, false
65		}
66		if raw.Objective == nil || raw.Good == nil || raw.Total == nil || raw.Comment == nil {
67			return nil, false
68		}
69		objective := *raw.Objective
70		if math.IsNaN(objective) || math.IsInf(objective, 0) || objective <= 0 || objective >= 1 {
71			return nil, false
72		}
73		good, ok := decodeRawSide(raw.Good)
74		if !ok {
75			return nil, false
76		}
77		total, ok := decodeRawSide(raw.Total)
78		if !ok {
79			return nil, false
80		}
81		return &sloDefinition{
82			objective: objective,
83			good:      good,
84			total:     total,
85			comment:   *raw.Comment,
86		}, true
87	}
88	
89	// ---- store operations ------------------------------------------------------
90	
91	func (s *metricStore) putSLO(d *sloDefinition) bool {
92		s.mu.Lock()
93		defer s.mu.Unlock()
94		_, existed := s.slos[d.id]
95		s.slos[d.id] = d
96		return !existed
97	}
98	
99	func (s *metricStore) getSLO(id string) (*sloDefinition, bool) {
100		s.mu.RLock()
101		defer s.mu.RUnlock()
102		d, ok := s.slos[id]
103		return d, ok
104	}
105	
106	func (s *metricStore) deleteSLO(id string) bool {
107		s.mu.Lock()
108		defer s.mu.Unlock()
109		if _, ok := s.slos[id]; !ok {
110			return false
111		}
112		delete(s.slos, id)
113		return true
114	}
115	
116	// snapshotSLOs returns all definitions sorted by id. Definition objects are
117	// immutable, so the pointers stay safe after the lock is released.
118	func (s *metricStore) snapshotSLOs() []*sloDefinition {
119		s.mu.RLock()
120		defer s.mu.RUnlock()
121		return s.snapshotSLOsLocked()
122	}
123	
124	func (s *metricStore) snapshotSLOsLocked() []*sloDefinition {
125		out := make([]*sloDefinition, 0, len(s.slos))
126		for _, d := range s.slos {
127			out = append(out, d)
128		}
129		sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
130		return out
131	}
132	
133	// counterSum sums current values of all matching counter series. ok is false
134	// when no counter series matches; gauges and histograms are ignored, so a
135	// selector matching only those counts as unavailable.
136	func (s *metricStore) counterSum(sel *ruleSelector) (sum float64, ok bool) {
137		for _, cur := range s.series {
138			if cur.typ != "counter" {
139				continue
140			}
141			if cur.name != sel.metric {
142				continue
143			}
144			matched := true
145			for k, v := range sel.labels {
146				got, exists := cur.labels[k]
147				if !exists || got != v {
148					matched = false
149					break
150				}
151			}
152			if !matched {
153				continue
154			}
155			sum += cur.value
156			ok = true
157		}
158		return sum, ok
159	}
160	
161	// ---- status evaluation -----------------------------------------------------
162	
163	type sloStatusOutput struct {
164		ID                        string   `json:"id"`
165		State                     string   `json:"state"`
166		GoodEvents                *float64 `json:"good_events"`
167		TotalEvents               *float64 `json:"total_events"`
168		Compliance                *float64 `json:"compliance"`
169		ErrorBudgetTotal          *float64 `json:"error_budget_total"`
170		ErrorBudgetRemaining      *float64 `json:"error_budget_remaining"`
171		ErrorBudgetRemainingRatio *float64 `json:"error_budget_remaining_ratio"`
172	}
173	
174	// evalSLOStatus computes every SLO definition against a single consistent
175	// snapshot of definitions and counter series; results are sorted by id.
176	//
177	// Each side sums the current values of matching counters only. A side with no
178	// matching counter, or a zero total, yields no_data. Non-finite aggregates or
179	// good exceeding total yield invalid_data. In both cases every numeric field
180	// is null. Otherwise compliance, budget totals and remaining amounts are
181	// derived from the event counts; remaining amounts may go negative.
182	func (s *metricStore) evalSLOStatus() []sloStatusOutput {
183		s.mu.RLock()
184		defer s.mu.RUnlock()
185	
186		defs := s.snapshotSLOsLocked()
187		out := make([]sloStatusOutput, 0, len(defs))
188		for _, d := range defs {
189			st := sloStatusOutput{ID: d.id}
190	
191			good, goodOK := s.counterSum(d.good)
192			total, totalOK := s.counterSum(d.total)
193			switch {
194			case !goodOK || !totalOK || total == 0:
195				st.State = "no_data"
196			case math.IsNaN(good) || math.IsInf(good, 0) ||
197				math.IsNaN(total) || math.IsInf(total, 0) || good > total:
198				st.State = "invalid_data"
199			default:
200				compliance := good / total
201				budgetTotal := total * (1 - d.objective)
202				remaining := budgetTotal - (total - good)
203				remainingRatio := remaining / budgetTotal
204	
205				st.State = "breached"
206				if compliance >= d.objective {
207					st.State = "met"
208				}
209				st.GoodEvents = &good
210				st.TotalEvents = &total
211				st.Compliance = &compliance
212				st.ErrorBudgetTotal = &budgetTotal
213				st.ErrorBudgetRemaining = &remaining
214				st.ErrorBudgetRemainingRatio = &remainingRatio
215			}
216			out = append(out, st)
217		}
218		return out
219	}
220	
221	// ---- HTTP handlers ---------------------------------------------------------
222	
223	func registerSLOHandlers(mux *http.ServeMux) {
224		mux.HandleFunc(slosPath, func(w http.ResponseWriter, r *http.Request) {
225			if r.Method != http.MethodGet {
226				w.Header().Set("Allow", http.MethodGet)
227				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
228				return
229			}
230			defs := tenantStore(r).snapshotSLOs()
231			body := make([]sloJSON, 0, len(defs))
232			for _, d := range defs {
233				body = append(body, sloWireJSON(d))
234			}
235			writeJSON(w, http.StatusOK, map[string]any{"slos": body})
236		})
237	
238		mux.HandleFunc(slosPrefix, func(w http.ResponseWriter, r *http.Request) {
239			store := tenantStore(r)
240			id := strings.TrimPrefix(r.URL.Path, slosPrefix)
241			switch r.Method {
242			case http.MethodGet, http.MethodDelete:
243				// Reads and deletions can only address an existing, syntactically
244				// valid SLO id; anything else is simply not found.
245				if id == "" || strings.Contains(id, "/") || !identPattern.MatchString(id) {
246					writeAPIError(w, "slo_not_found", http.StatusNotFound)
247					return
248				}
249				if r.Method == http.MethodGet {
250					handleSLOGet(w, id, store)
251				} else {
252					handleSLODelete(w, id, store)
253				}
254			case http.MethodPut:
255				// A structurally nested path is outside this resource subtree;
256				// an identifier-shaped but invalid id is a bad identifier.
257				if id == "" || strings.Contains(id, "/") {
258					writeAPIError(w, "slo_not_found", http.StatusNotFound)
259					return
260				}
261				if !identPattern.MatchString(id) {
262					writeAPIError(w, "invalid_slo", http.StatusBadRequest)
263					return
264				}
265				handleSLOPut(w, r, id, store)
266			default:
267				w.Header().Set("Allow", "GET, PUT, DELETE")
268				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
269			}
270		})
271	
272		mux.HandleFunc(sloStatusPath, func(w http.ResponseWriter, r *http.Request) {
273			if r.Method != http.MethodGet {
274				w.Header().Set("Allow", http.MethodGet)
275				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
276				return
277			}
278			writeJSON(w, http.StatusOK, map[string]any{"slos": tenantStore(r).evalSLOStatus()})
279		})
280	}
281	
282	func handleSLOGet(w http.ResponseWriter, id string, store *metricStore) {
283		d, ok := store.getSLO(id)
284		if !ok {
285			writeAPIError(w, "slo_not_found", http.StatusNotFound)
286			return
287		}
288		writeJSON(w, http.StatusOK, sloWireJSON(d))
289	}
290	
291	func handleSLOPut(w http.ResponseWriter, r *http.Request, id string, store *metricStore) {
292		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
293		if err != nil || mediaType != "application/json" {
294			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
295			return
296		}
297	
298		body, err := io.ReadAll(r.Body)
299		if err != nil {
300			writeAPIError(w, "invalid_slo", http.StatusBadRequest)
301			return
302		}
303	
304		def, ok := decodeSLO(body)
305		if !ok {
306			writeAPIError(w, "invalid_slo", http.StatusBadRequest)
307			return
308		}
309		def.id = id
310	
311		created := store.putSLO(def)
312		status := http.StatusOK
313		if created {
314			status = http.StatusCreated
315		}
316		writeJSON(w, status, sloWireJSON(def))
317	}
318	
319	func handleSLODelete(w http.ResponseWriter, id string, store *metricStore) {
320		if !store.deleteSLO(id) {
321			writeAPIError(w, "slo_not_found", http.StatusNotFound)
322			return
323		}
324		w.WriteHeader(http.StatusNoContent)
325	}
