// ---- expression AST --------------------------------------------------------

// queryExpr is one parsed expression: either a bare selector (aggregate ==
// "") or one of sum/avg/min/max, optionally grouped by non-empty by labels.
type queryExpr struct {
	aggregate string
	by        []string
	metric    string
	selector  map[string]string
}

var queryAggregates = map[string]bool{
	"sum": true,
	"avg": true,
	"min": true,
	"max": true,
}

// ---- expression parser -----------------------------------------------------

type exprParser struct {
	s string
	p int
}

// parseQueryExpr parses the single expression accepted by GET /api/v1/query.
// Whitespace is ASCII only and may surround any punctuation. The grammar:
//
//	expr        := selector | aggregation
//	aggregation := aggIdent ("by" "(" ident ("," ident)* ")")? "(" selector ")"
//	selector    := ident "(" "=" jsonString ("," ident "=" jsonString)* ","? ")"
//
// where the selector brace set is { } rather than parentheses. Duplicate
// matchers or grouping labels, nested aggregations, unknown functions and any
// trailing input are rejected.
func parseQueryExpr(in string) (*queryExpr, bool) {
	p := &exprParser{s: in}
	p.skipSpaces()

	word, ok := p.parseIdent()
	if !ok {
		return nil, false
	}
	p.skipSpaces()

	e := &queryExpr{}
	if queryAggregates[word] {
		e.aggregate = word
		if p.hasIdent("by") {
			p.p += 2
			p.skipSpaces()
			if !p.expect('(') {
				return nil, false
			}
			seen := make(map[string]bool)
			for {
				p.skipSpaces()
				label, ok := p.parseIdent()
				if !ok {
					return nil, false
				}
				if seen[label] {
					return nil, false
				}
				seen[label] = true
				e.by = append(e.by, label)
				p.skipSpaces()
				switch p.next() {
				case ',':
					p.p++
					continue
				case ')':
					p.p++
				default:
					return nil, false
				}
				break
			}
			p.skipSpaces()
		}
		if !p.expect('(') {
			return nil, false
		}
		p.skipSpaces()
		if !p.parseSelectorInto(e) {
			return nil, false
		}
		p.skipSpaces()
		if !p.expect(')') {
			return nil, false
		}
	} else {
		// The first identifier is the metric name; the selector body follows.
		e.metric = word
		if !p.expect('{') {
			return nil, false
		}
		if !p.parseMatcherListInto(e) {
			return nil, false
		}
	}

	p.skipSpaces()
	if p.p != len(p.s) {
		return nil, false
	}
	return e, true
