// name; used for selectors nested inside an aggregation call.
func (p *exprParser) parseSelectorInto(e *queryExpr) bool {
	name, ok := p.parseIdent()
	if !ok {
		return false
	}
	e.metric = name
	p.skipSpaces()
	if !p.expect('{') {
		return false
	}
