		p.p++
		return true
	}
	for {
		p.skipSpaces()
		key, ok := p.parseIdent()
		if !ok {
			return false
		}
		if _, dup := e.selector[key]; dup {
			return false
		}
		p.skipSpaces()
		if !p.expect('=') {
			return false
		}
