				break
			}
		}
		if !ok {
			continue
		}
		if math.IsNaN(cur.value) || math.IsInf(cur.value, 0) {
			return nil, false
		}
		matched = append(matched, matchedSeries{labels: copyLabels(cur.labels), value: cur.value})
	}

	if e.aggregate == "" {
		out := make([]querySample, 0, len(matched))
		for _, m := range matched {
			out = append(out, querySample{Labels: m.labels, Value: m.value})
		}
		sort.Slice(out, func(i, j int) bool {
			return compareLabels(out[i].Labels, out[j].Labels) < 0
		})
		return out, true
	}

	groups := make(map[string]*querySample)
	order := make([]map[string]string, 0)
	counts := make(map[string]int)
	for _, m := range matched {
		projected := make(map[string]string, len(e.by))
		for _, label := range e.by {
			if v, ok := m.labels[label]; ok {
				projected[label] = v
			}
		}
		key := seriesKey("", projected)
		g, seen := groups[key]
		if !seen {
			g = &querySample{Labels: projected, Value: m.value}
			groups[key] = g
			order = append(order, projected)
		}
		switch e.aggregate {
		case "sum":
			g.Value += m.value
		case "avg":
			g.Value += m.value
			counts[key]++
		case "min":
			if m.value < g.Value || counts[key] == 0 {
				g.Value = m.value
			}
		case "max":
			if m.value > g.Value || counts[key] == 0 {
				g.Value = m.value
			}
		}
		if !seen {
			counts[key] = 1
		} else if e.aggregate != "avg" {
			counts[key]++
		} else {
			counts[key]++
		}
	}

	out := make([]querySample, 0, len(order))
