		result, finite := tenantStore(r).executeQuery(expr)
		if !finite {
			writeAPIError(w, "invalid_query_data", http.StatusUnprocessableEntity)
			return
		}
		writeJSON(w, http.StatusOK, queryResponse{ResultType: "vector", Result: result})
	})
}

