package server

import (
	"encoding/json"
	"net/http"
	"net/url"
	"testing"
)

func queryExpr(t *testing.T, h http.Handler, expr string) *responseResult {
	t.Helper()
	return queryExprAs(t, h, expr, "")
}

type responseResult struct {
	t   *testing.T
	rec *recorderResult
}

type recorderResult = interface {
	Code() int
}

func queryExprAs(t *testing.T, h http.Handler, expr, tenant string) *responseResultShim {
	t.Helper()
	target := queryPath + "?expr=" + url.QueryEscape(expr)
	req := newQueryRequest(target, tenant)
	return serveQuery(t, h, req)
}

func queryRaw(t *testing.T, h http.Handler, rawQuery, tenant string) *responseResultShim {
	t.Helper()
	req := newQueryRequest(queryPath+"?"+rawQuery, tenant)
	return serveQuery(t, h, req)
}

func newQueryRequest(target, tenant string) *http.Request {
	req := httptestNewRequest(http.MethodGet, target, nil)
	if tenant != "" {
		req.Header.Set(tenantHeader, tenant)
	}
	return req
}

func serveQuery(t *testing.T, h http.Handler, req *http.Request) *responseResultShim {
	rec := httptestNewRecorder()
	h.ServeHTTP(rec, req)
	return &responseResultShim{t: t, rec: rec}
}

type responseResultShim struct {
	t   *testing.T
	rec *httptestResponseRecorder
}

func (r *responseResultShim) expectVector() []map[string]any {
	r.t.Helper()
	if r.rec.Code != http.StatusOK {
		r.t.Fatalf("status = %d, want 200, body=%q", r.rec.Code, r.rec.Body.String())
	}
	var payload struct {
		ResultType string              `json:"result_type"`
		Result     []map[string]any    `json:"result"`
	}
	if err := json.Unmarshal(r.rec.Body.Bytes(), &payload); err != nil {
		r.t.Fatalf("invalid JSON body %q: %v", r.rec.Body.String(), err)
	}
	if payload.ResultType != "vector" {
		r.t.Fatalf("result_type = %q, want vector", payload.ResultType)
	}
	return payload.Result
}

func (r *responseResultShim) expectError(status int, code string) {
	r.t.Helper()
	expectErrorCode(r.t, r.rec, status, code)
}

func (r *responseResultShim) expectAllow(method string) {
	r.t.Helper()
	if got := r.rec.Header().Get("Allow"); got != method {
		r.t.Fatalf("Allow = %q, want %q", got, method)
	}
}

func seedQuerySeries(t *testing.T, h http.Handler) {
	t.Helper()
	body := `{"samples":[
		{"name":"hits","type":"counter","labels":{"route":"/a","zone":"z1"},"value":3},
		{"name":"hits","type":"counter","labels":{"route":"/b","zone":"z1"},"value":5},
		{"name":"hits","type":"counter","labels":{"route":"/c","zone":"z2"},"value":7},
		{"name":"temp","type":"gauge","labels":{"zone":"z1"},"value":10},
		{"name":"hits","type":"histogram","labels":{"route":"/d","zone":"z1"},"value":1,"buckets":[1,2]}
	]}`
	rec := postMetrics(t, h, body, "")
	if rec.Code != http.StatusAccepted {
		t.Fatalf("seed failed: %d %s", rec.Code, rec.Body.String())
	}
}

func TestQueryPlainSelector(t *testing.T) {
	h := Handler()
	seedQuerySeries(t, h)

	// Full label sets, sorted by the normalized full-label ordering.
	got := queryExpr(t, h, `hits{zone="z1"}`).expectVector()
	if len(got) != 2 {
		t.Fatalf("got %d samples: %v", len(got), got)
	}
	if labelsOf(got[0])["route"] != "/a" || num(got[0]) != 3 {
		t.Fatalf("first sample = %v", got[0])
	}
	if labelsOf(got[1])["route"] != "/b" || num(got[1]) != 5 {
		t.Fatalf("second sample = %v", got[1])
	}

	// The histogram never participates.
	got = queryExpr(t, h, `hits{route="/d"}`).expectVector()
	if len(got) != 0 {
		t.Fatalf("histogram must not match, got %v", got)
	}

	// Empty selector is legal and matches every series of the metric.
	got = queryExpr(t, h, `hits{}`).expectVector()
	if len(got) != 3 {
		t.Fatalf("empty selector matches %d series, want 3: %v", len(got), got)
	}

	// Gauges participate as well.
	got = queryExpr(t, h, `temp{}`).expectVector()
	if len(got) != 1 || num(got[0]) != 10 {
		t.Fatalf("gauge query = %v", got)
	}
}

func TestQueryUnknownMetricIsEmpty(t *testing.T) {
	h := Handler()
	if got := queryExpr(t, h, `missing{}`).expectVector(); len(got) != 0 {
		t.Fatalf("want empty result, got %v", got)
	}
}

func TestQueryJSONStringEscaping(t *testing.T) {
	h := Handler()
	body := `{"samples":[
		{"name":"hits","type":"counter","labels":{"route":"a\"b\\c","zone":"中"},"value":4}
	]}`
	if rec := postMetrics(t, h, body, ""); rec.Code != http.StatusAccepted {
		t.Fatalf("seed failed: %d %s", rec.Code, rec.Body.String())
	}
	got := queryExpr(t, h, `hits{route="a\"b\\c",zone="中"}`).expectVector()
	if len(got) != 1 || num(got[0]) != 4 {
		t.Fatalf("escaped selector result = %v", got)
	}
}

func TestQueryAggregationsWithoutBy(t *testing.T) {
	h := Handler()
	seedQuerySeries(t, h)

	cases := []struct {
		expr string
		want float64
	}{
		{`sum(hits{zone="z1"})`, 8},
		{`avg(hits{zone="z1"})`, 4},
		{`min(hits{zone="z1"})`, 3},
		{`max(hits{zone="z1"})`, 8},
	}
	for _, tc := range cases {
		got := queryExpr(t, h, tc.expr).expectVector()
		if len(got) != 1 {
			t.Fatalf("%s: want single group, got %v", tc.expr, got)
		}
		if len(labelsOf(got[0])) != 0 {
			t.Fatalf("%s: group labels = %v, want {}", tc.expr, labelsOf(got[0]))
		}
		if num(got[0]) != tc.want {
